def unit_of_work(metadata=None, timeout=None):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            from neo4j import dbms

            # Create a new transaction using the decorated function
            tx = dbms.begin()

            # Set the metadata and timeout
            tx.set_meta_data(metadata)
            tx.set_timeout(timeout)

            # Execute the decorated function
            result = func(tx, *args, **kwargs)

            # Commit or rollback the transaction
            if tx.success:
                tx.commit()
            else:
                tx.rollback()

            return result

    return decorator

