    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    """
    new_dict = {}
    for k, v in manifest_dict.items():
        if isinstance(v, (list, dict)):
            new_dict[k] = v
        elif first_level and v in Model.ServiceClass.Service.Meta_.Meta.identifying_fields:
            new_dict[k] = v
        else:
            new_dict[k] = None
    return new_dict

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Generates a partial observer schema from a part of a Kubernetes resource.

    Args:
        manifest_dict (dict): Partial Kubernetes resource
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema
    """
    new_dict = {}
    for key, value in manifest_dict.items():
        if isinstance(value, list) or isinstance(value, dict):
            new_dict[key] = generate_default_observer_schema_dict(value)
        else:
            # Replace all non-list and non-dict values by None
            new_dict[key] = None

    if first_level:
        # Copy values of identifying fields from manifest_dict
        for key, value in manifest_dict.items():
            if key in IDENTIFYING_FIELDS:
                new_dict[key] = value

    return new_dict

