def formatmany(
    self,
    sql: AnyStr,
    many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    # Convert the SQL query to use the out-style parameters instead of the in-style parameters
    # Many_params contains each set of in-style parameters

    # Check if the sql query is valid
    if sql is None or many_params is None:
        raise ValueError("Invalid input")

    # Convert the in-style parameters to out-style parameters
    out_params = []
    for params in many_params:
        # Check if the params is a valid dictionary
        if isinstance(params, dict):
            out_params.append(self._convert_dict_to_out_style(params))
        # Check if the params is a valid list
        elif isinstance(params, list):
            out_params.append(self._convert_list_to_out_style(params))
        else:
            raise ValueError("Invalid input")

    # Format the SQL query with the out-style parameters
    out_sql = self._format_sql(sql)

    return out_sql, out_params

def _convert_dict_to_out_style(
    self,
    params: Dict[Union[str, int], Any],
) -> Dict[str, Any]:
    # Convert the in-style dictionary to an out-style dictionary
    out_dict = {}
    for key, value in params.items():
        out_dict[':' + str(key)] = value
    return out_dict

def _convert_list_to_out_style(
    self,
    params: List[Any],
) -> List[Any]:
    # Convert the in-style list to an out-style list
    out_list = []
    for value in params:
        out_list.append(value)
    return out_list

def _format_sql(
    self,
    sql: AnyStr,
) -> AnyStr:
    # Format the SQL query with the out-style parameters
    out_sql = sql + " "
    for param in out_params:
        out_sql += "$" + str(param) + " "
    return out_sql
