def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.

    """
    if not version:
        return "1.0.0"

    parts = version.split(".")
    release, major, minor = parts[0], int(parts[1]), int(parts[2])

    if minor == 9:
        minor = 0
        if major == 9:
            major = 0
            release = str(int(release) + 1)

    return ".".join([release, str(major + 1), str(minor + 1)])

