def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    include_groups = set()
    for config_file in parser_dict['configfile']:
        with open(config_file) as f:
            config = f.read()
        for line in config.splitlines():
            if line.strip().startswith('include'):
                include_groups.union(set(self._parse_include_line(line)))
    return include_groups

def _parse_include_line(self, line):
    """Parses a single include line from a spec file. """
    match_obj = re.match(r'(include|include-only) (.*)', line)
    if not match_obj:
        raise ValueError('Invalid include line: ' + line)
    return match_obj.group(2).split(' ')

